MINIMAX_VL_01_IMAGE_GRID_PINPOINTS = [
    [336, 336],
    [336, 672],
    [336, 1008],
    [336, 1344],
    [336, 1680],
    [336, 2016],
    [672, 336],
    [672, 672],
    [672, 1008],
    [672, 1344],
    [672, 1680],
    [672, 2016],
    [1008, 336],
    [1008, 672],
    [1008, 1008],
    [1008, 1344],
    [1008, 1680],
    [1008, 2016],
    [1344, 336],
    [1344, 672],
    [1344, 1008],
    [1344, 1344],
    [1680, 336],
    [1680, 672],
    [1680, 1008],
    [2016, 336],
    [2016, 672],
    [2016, 1008],
]


class MiniMaxVL01ImageProcessorKwargs(ImagesKwargs, total=False):
    r"""
    process_image_mode (`str`, *optional*, defaults to `"anyres"`):
        Image processing mode. The released checkpoint supports only `"anyres"`.
    patch_size (`int`, *optional*, defaults to `14`):
        Patch size of the CLIP vision encoder, used when expanding image placeholders.
    """

    image_grid_pinpoints: list[list[int]]

    process_image_mode: str
    patch_size: int


@auto_docstring
class MiniMaxVL01ImageProcessorPil(PilBackend):
    model_input_names = ["pixel_values", "image_sizes"]
    valid_kwargs = MiniMaxVL01ImageProcessorKwargs
    resample = PILImageResampling.BICUBIC
    image_mean = OPENAI_CLIP_MEAN
    image_std = OPENAI_CLIP_STD
    size = {"height": 336, "width": 336}
    default_to_square = False
    crop_size = None
    do_resize = True
    do_center_crop = False
    do_rescale = True
    do_normalize = True
    do_convert_rgb = True
    do_pad = False
    image_grid_pinpoints = MINIMAX_VL_01_IMAGE_GRID_PINPOINTS
    process_image_mode = "anyres"
    patch_size = 14

    def __init__(self, **kwargs: Unpack[MiniMaxVL01ImageProcessorKwargs]):
        super().__init__(**kwargs)
        if kwargs.get("process_image_mode", self.process_image_mode) != "anyres":
            raise ValueError("MiniMax-VL-01 supports only `process_image_mode='anyres'`.")

    @auto_docstring
    def preprocess(
        self, images: ImageInput | list[ImageInput], *args, **kwargs: Unpack[MiniMaxVL01ImageProcessorKwargs]
    ) -> BatchFeature:
        return super().preprocess(images, *args, **kwargs)

    def _get_padding_size(self, original_resolution: tuple, target_resolution: tuple):
        """Get padding size for patching (returns tuple format for np.pad)."""
        original_height, original_width = original_resolution
        target_height, target_width = target_resolution
        paste_x, r_x = divmod(target_width - original_width, 2)
        paste_y, r_y = divmod(target_height - original_height, 2)
        return (paste_y, paste_y + r_y), (paste_x, paste_x + r_x)

    def _resize_for_patching(
        self,
        image: np.ndarray,
        target_resolution: tuple,
        resample: PILImageResampling,
    ) -> np.ndarray:
        """Resizes an image to a target resolution while maintaining aspect ratio."""
        original_height, original_width = image.shape[-2:]
        target_height, target_width = target_resolution
        if original_width / original_height > target_width / target_height:
            new_width = target_width
            new_height = int(target_width * original_height / original_width)
        else:
            new_height = target_height
            new_width = int(target_height * original_width / original_height)
        return self.resize(
            image=image,
            size=SizeDict(height=new_height, width=new_width),
            resample=resample,
        )

    def _pad_for_patching(self, image: np.ndarray, target_resolution: tuple) -> np.ndarray:
        """Pad an image to a target resolution while maintaining aspect ratio."""
        new_resolution = get_patch_output_size(image, target_resolution, input_data_format=ChannelDimension.FIRST)
        padding_hw = self._get_padding_size(new_resolution, target_resolution)

        # For channels_first format (C, H, W), add (0, 0) for channel dimension
        # padding_hw is ((before_h, after_h), (before_w, after_w))
        # np.pad expects ((before_C, after_C), (before_H, after_H), (before_W, after_W))
        padding = ((0, 0), padding_hw[0], padding_hw[1])

        # Use np.pad directly for patching padding
        padded_image = np.pad(image, padding, mode="constant", constant_values=0)

        return padded_image

    def get_image_patches(
        self,
        image: np.ndarray,
        grid_pinpoints: list[list[int]],
        size: tuple,
        patch_size: int,
        resample: PILImageResampling,
    ) -> list[np.ndarray]:
        """Process an image with variable resolutions by dividing it into patches."""
        if not isinstance(grid_pinpoints, list):
            raise TypeError("grid_pinpoints must be a list of possible resolutions.")

        possible_resolutions = grid_pinpoints

        image_size = image.shape[-2:]
        best_resolution = select_best_resolution(image_size, possible_resolutions)
        resized_image = self._resize_for_patching(image, best_resolution, resample=resample)
        padded_image = self._pad_for_patching(resized_image, best_resolution)

        patches = divide_to_patches(padded_image, patch_size=patch_size)

        size_height, size_width = size
        resized_original_image = self.resize(
            image=image,
            size=SizeDict(height=size_height, width=size_width),
            resample=resample,
        )

        image_patches = [resized_original_image] + patches

        return image_patches

    def _pad_for_batching(
        self,
        pixel_values: list[np.ndarray],
    ) -> list[np.ndarray]:
        """Pads images on the `num_of_patches` dimension with zeros to form a batch of same number of patches."""
        max_patch = max(len(x) for x in pixel_values)
        # Use np.pad directly for patch dimension padding
        padded_values = []
        for image in pixel_values:
            # Padding format: ((before_dim0, after_dim0), (before_dim1, after_dim1), ...)
            padding = ((0, max_patch - image.shape[0]), (0, 0), (0, 0), (0, 0))
            padded_image = np.pad(image, padding, mode="constant", constant_values=0)
            padded_values.append(padded_image)

        return padded_values

    def _preprocess(
        self,
        images: list[np.ndarray],
        do_resize: bool,
        size: SizeDict,
        image_grid_pinpoints: list[list[int]],
        resample: "PILImageResampling | None",
        do_center_crop: bool,
        crop_size: SizeDict,
        do_rescale: bool,
        rescale_factor: float,
        do_normalize: bool,
        image_mean: float | list[float] | None,
        image_std: float | list[float] | None,
        do_pad: bool | None,
        return_tensors: str | TensorType | None,
        **kwargs,
    ) -> BatchFeature:
        """Custom preprocessing for LLaVA-NeXT with patch processing."""
        if kwargs.get("process_image_mode", self.process_image_mode) != "anyres":
            raise ValueError("MiniMax-VL-01 supports only `process_image_mode='anyres'`.")

        processed_images = []
        image_sizes = []
        if size and size.height and size.width:
            size_tuple = (size.height, size.width)
        else:
            size_tuple = (size.shortest_edge, size.shortest_edge)
        patch_size = size.height if size and size.height else size.shortest_edge

        for image in images:
            image_patches = self.get_image_patches(
                image,
                image_grid_pinpoints,
                size=size_tuple,
                patch_size=patch_size,
                resample=resample,
            )
            pixel_values = []
            for patch in image_patches:
                if do_resize:
                    patch = self.resize(image=patch, size=size, resample=resample)
                if do_center_crop:
                    patch = self.center_crop(image=patch, size=crop_size)
                if do_rescale:
                    patch = self.rescale(image=patch, scale=rescale_factor)
                if do_normalize:
                    patch = self.normalize(image=patch, mean=image_mean, std=image_std)
                pixel_values.append(patch)
            processed_images.append(np.asarray(pixel_values))
            image_sizes.append(image.shape[-2:])

        pixel_values = np.concatenate(processed_images, axis=0)
        return BatchFeature(
            data={"pixel_values": pixel_values, "image_sizes": image_sizes}, tensor_type=return_tensors
        )


__all__ = ["MiniMaxVL01ImageProcessorPil"]
